"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One destination in the sidebar. */
export interface SidebarCollapseItem {
  id: string;
  label: string;
  icon: ReactNode;
  /** With an `href` the item is a link; without one it is a button. */
  href?: string;
}

/**
 * Props for a collapsing sidebar. The active item and the collapsed state each
 * work controlled (`value`, `collapsed`) or on their own (`defaultValue`, `defaultCollapsed`).
 */
export type SidebarCollapseProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue"> & {
  items: SidebarCollapseItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
};

// Critically damped: the panel reaches its width fast and does not wobble.
const WIDTH_SPRING: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const LABEL: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };
// 8px of padding on each side of a 36px icon slot, plus the 1px border, so the icons never move.
const COLLAPSED_WIDTH = 53;
const EXPANDED_WIDTH = 208;

const ROW =
  "relative flex min-h-11 w-full cursor-pointer touch-manipulation items-center rounded-lg text-left text-sm outline-none before:absolute before:inset-y-0 before:-inset-x-1 motion-safe:transition-colors motion-safe:duration-150 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset sm:min-h-9";

/**
 * An app sidebar that collapses to its icons. The width springs, the labels
 * fade and slide away, and a collapsed item names itself in a tooltip.
 */
export function SidebarCollapse({
  items,
  value,
  defaultValue,
  onValueChange,
  collapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  className,
  "aria-label": ariaLabel = "Main",
  ...rootProps
}: SidebarCollapseProps) {
  const [ownValue, setOwnValue] = useState(defaultValue ?? items[0]?.id);
  const [ownCollapsed, setOwnCollapsed] = useState(defaultCollapsed);
  // `y` is the middle of the hovered or focused item, measured from the top of the sidebar.
  const [tip, setTip] = useState<{ id: string; y: number } | null>(null);
  const activeId = value ?? ownValue;
  const isCollapsed = collapsed ?? ownCollapsed;
  const reduceMotion = useReducedMotion();
  const navId = useId();
  const root = useRef<HTMLDivElement>(null);
  const named = isCollapsed ? items.find((item) => item.id === tip?.id) : undefined;

  useEffect(() => {
    if (!tip) return;
    const hideOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setTip(null);
    };
    document.addEventListener("keydown", hideOnEscape);
    return () => document.removeEventListener("keydown", hideOnEscape);
  }, [tip]);

  const toggle = () => {
    if (collapsed === undefined) setOwnCollapsed(!isCollapsed);
    onCollapsedChange?.(!isCollapsed);
    setTip(null);
  };

  const select = (id: string) => {
    if (value === undefined) setOwnValue(id);
    onValueChange?.(id);
  };

  const name = (id: string, row: HTMLElement) => {
    const box = row.getBoundingClientRect();
    const top = root.current?.getBoundingClientRect().top ?? 0;
    setTip({ id, y: box.top - top + box.height / 2 });
  };

  const label = (text: string) => (
    // The label stays in the page when collapsed, so the item keeps its accessible name.
    <motion.span
      initial={false}
      animate={{ opacity: isCollapsed ? 0 : 1, x: isCollapsed && !reduceMotion ? -6 : 0 }}
      transition={LABEL}
      className="pr-3 whitespace-nowrap"
    >
      {text}
    </motion.span>
  );

  return (
    <div {...rootProps} ref={root} className={cn("relative flex h-full", className)}>
      <motion.div
        initial={false}
        // Width is a layout property, but one panel changes it on one press.
        animate={{ width: isCollapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
        transition={reduceMotion ? INSTANT : WIDTH_SPRING}
        className="flex h-full flex-col gap-1 overflow-hidden border-r border-border bg-card p-2 text-foreground"
      >
        <button
          type="button"
          aria-label="Sidebar"
          aria-expanded={!isCollapsed}
          aria-controls={navId}
          onClick={toggle}
          className={cn(ROW, "text-muted-foreground hover:bg-muted hover:text-foreground")}
        >
          <span className="flex size-9 shrink-0 items-center justify-center">
            <svg aria-hidden="true" viewBox="0 0 20 20" fill="currentColor" fillRule="evenodd" className="size-5">
              <path d="M3 4h14a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1zm5 2v8h8V6z" />
            </svg>
          </span>
          {label(isCollapsed ? "Expand" : "Collapse")}
        </button>
        <nav id={navId} aria-label={ariaLabel}>
          <ul className="flex flex-col gap-0.5" onPointerLeave={() => setTip(null)}>
            {items.map((item) => {
              const active = item.id === activeId;
              const shared = {
                "aria-current": active ? ("page" as const) : undefined,
                onClick: () => select(item.id),
                onPointerEnter: (event: { pointerType: string; currentTarget: HTMLElement }) => {
                  // A finger cannot hover; a tap would leave the tooltip stuck open.
                  if (event.pointerType !== "touch") name(item.id, event.currentTarget);
                },
                onFocus: (event: { currentTarget: HTMLElement }) => name(item.id, event.currentTarget),
                onBlur: () => setTip(null),
                className: cn(
                  ROW,
                  // The active item is filled and heavier, so it never rests on colour alone.
                  active ? "bg-muted font-medium text-foreground" : "text-muted-foreground hover:text-foreground",
                ),
              };
              const body = (
                <>
                  <span className="flex size-9 shrink-0 items-center justify-center">{item.icon}</span>
                  {label(item.label)}
                </>
              );
              return (
                <li key={item.id}>
                  {item.href ? (
                    <a href={item.href} {...shared}>
                      {body}
                    </a>
                  ) : (
                    <button type="button" {...shared}>
                      {body}
                    </button>
                  )}
                </li>
              );
            })}
          </ul>
        </nav>
      </motion.div>
      <AnimatePresence>
        {tip && named ? (
          // Hidden from screen readers: the item already carries its label.
          <motion.div
            key="tooltip"
            aria-hidden="true"
            data-tooltip=""
            initial={{ y: tip.y, opacity: 0, x: reduceMotion ? 0 : -4 }}
            animate={{ y: tip.y, opacity: 1, x: 0 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ y: INSTANT, default: LABEL }}
            // A zero-height anchor at the item's middle; the bubble centres itself on it.
            className="pointer-events-none absolute top-0 left-full z-10 ml-2 h-0"
          >
            <span className="absolute top-0 left-0 -translate-y-1/2 rounded-md bg-foreground px-2 py-1 text-xs font-medium whitespace-nowrap text-background shadow-md">
              {named.label}
            </span>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
